-- +goose Up

CREATE TABLE IF NOT EXISTS access_grant (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    grant_id                 uuid         NOT NULL,
    grant_key                semantic_key NOT NULL,
    principal_ref            text NOT NULL,
    entitlement_ref          text NOT NULL,
    source                   text NOT NULL,
    status                   text NOT NULL DEFAULT 'PENDING',
    effective_from           date         NOT NULL,
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, grant_id),
    CONSTRAINT access_grant_key_unique UNIQUE (tenant_id, grant_key),
    CONSTRAINT access_grant_source_check CHECK (source IN ('BIRTHRIGHT', 'REQUEST', 'DELEGATION', 'EMERGENCY', 'MANUAL')),
    CONSTRAINT access_grant_status_check CHECK (status IN ('PENDING', 'GRANTED', 'REVOKED', 'EXPIRED')),
    CONSTRAINT access_grant_knowledge_order CHECK (known_at <= recorded_at)
);

CREATE INDEX IF NOT EXISTS access_grant_recorded
    ON access_grant (tenant_id, recorded_at DESC);

ALTER TABLE access_grant ENABLE ROW LEVEL SECURITY;
ALTER TABLE access_grant FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON access_grant
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE ON access_grant TO hcmnext_app;

CREATE TABLE IF NOT EXISTS access_operation (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    operation_id             uuid         NOT NULL,
    grant_id                 uuid         NOT NULL,
    revision_sequence        bigint       NOT NULL,
    semantic_operation       text NOT NULL,
    expected_prior_state     text NOT NULL,
    new_state                text NOT NULL,
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, operation_id),
    CONSTRAINT access_operation_revision_positive CHECK (revision_sequence >= 1),
    CONSTRAINT access_operation_knowledge_order CHECK (known_at <= recorded_at),
    FOREIGN KEY (tenant_id, grant_id) REFERENCES access_grant (tenant_id, grant_id)
);

CREATE INDEX IF NOT EXISTS access_operation_recorded
    ON access_operation (tenant_id, recorded_at DESC);

CREATE OR REPLACE TRIGGER access_operation_append_only
    BEFORE UPDATE OR DELETE ON access_operation
    FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

REVOKE UPDATE, DELETE ON access_operation FROM PUBLIC;

ALTER TABLE access_operation ENABLE ROW LEVEL SECURITY;
ALTER TABLE access_operation FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON access_operation
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT ON access_operation TO hcmnext_app;

